+/// Opt-in bounded capture of the balance call to canonical_bits only.
+#[cfg(feature = "formal-observer")]
+pub mod inspection {
+    use super::*;
+    use commonware_cryptography::zk::circuit::CircuitIdx;
+    use std::cell::RefCell;
+    #[derive(Clone, PartialEq, Eq)]
+    pub enum Observed { Source(CircuitIdx), Native(Scalar) }
+    #[derive(Default)]
+    struct State { spend: bool, active: bool, steps: Vec<[Observed;6]>, target: Option<CircuitIdx>, result: Option<(CircuitIdx, Vec<CircuitIdx>, CircuitIdx)> }
+    thread_local! { static STATE: RefCell<Option<State>> = const { RefCell::new(None) }; }
+    pub struct Capture { _thread: std::marker::PhantomData<std::rc::Rc<()>> }
+    impl Drop for Capture { fn drop(&mut self) { STATE.with(|state| *state.borrow_mut() = None); } }
+    pub fn begin() -> anyhow::Result<Capture> {
+        STATE.with(|state| {
+            let mut state = state.borrow_mut();
+            anyhow::ensure!(state.is_none(), "nested canonical balance capture");
+            *state = Some(State::default());
+            Ok(Capture { _thread: std::marker::PhantomData })
+        })
+    }
+    /// Reuse the same bounded comparator observer for the actual spend call.
+    pub fn begin_spend() -> anyhow::Result<Capture> {
+        let capture = begin()?;
+        STATE.with(|state| state.borrow_mut().as_mut().expect("canonical state").spend = true);
+        Ok(capture)
+    }
+    pub(crate) fn spend_target(value: &Var<'_, Scalar>) {
+        STATE.with(|state| {
+            if let Some(state) = state.borrow_mut().as_mut().filter(|state| state.spend) {
+                assert!(state.target.is_none(), "multiple spend randomizer targets");
+                state.target = Some(value.inspect_circuit_idx().expect("native spend randomizer"));
+            }
+        });
+    }
+    pub(crate) fn target(value: &Var<'_, Scalar>) {
+        STATE.with(|state| {
+            if let Some(state) = state.borrow_mut().as_mut() {
+                if state.spend { return; }
+                assert!(state.target.is_none(), "multiple balance blinding targets");
+                state.target = Some(value.inspect_circuit_idx().expect("native balance blinding"));
+            }
+        });
+    }
+    pub(super) fn start_comparison(value: &Var<'_, Scalar>) {
+        STATE.with(|state| {
+            if let Some(state) = state.borrow_mut().as_mut() {
+                state.active = state.target.is_some() && value.inspect_circuit_idx() == state.target;
+            }
+        });
+    }
+    pub(crate) fn step<'ctx>(before: &Var<'ctx, Scalar>, left: &Var<'ctx, Scalar>, right: &Var<'ctx, Scalar>, factor: &Var<'ctx, Scalar>, product: &Var<'ctx, Scalar>, after: &Var<'ctx, Scalar>) {
+        STATE.with(|state| {
+            let mut state = state.borrow_mut();
+            let Some(state) = state.as_mut() else { return; };
+            if !state.active { return; }
+            assert!(state.steps.len() < 252, "canonical comparator steps exceed bound");
+            state.steps.push([before,left,right,factor,product,after].map(|v| match v.inspect_circuit_idx() {
+                Some(index) => Observed::Source(index),
+                None => Observed::Native(v.inspect_native().expect("invalid observed variable").clone()),
+            }));
+        });
+    }
+    pub(super) fn record(value: &Var<'_, Scalar>, bits: &[BoolVar<'_, Scalar>], ending: &Var<'_, Scalar>) {
+        STATE.with(|state| {
+            let mut state = state.borrow_mut();
+            let Some(state) = state.as_mut() else { return; };
+            let Some(target) = state.target else { return; };
+            if value.inspect_circuit_idx() != Some(target) { return; }
+            assert!(state.result.is_none() && bits.len() == 252, "unexpected canonical capture");
+            assert!(state.steps.len() == 252, "canonical comparison steps changed");
+            state.active = false;
+            state.result = Some((target,
+                bits.iter().map(|bit| bit.var().inspect_circuit_idx().expect("native canonical bit")).collect(),
+                ending.inspect_circuit_idx().expect("native canonical endpoint")));
+        });
+    }
+    pub fn take() -> anyhow::Result<(CircuitIdx, Vec<CircuitIdx>, CircuitIdx, Vec<[Observed;6]>)> {
+        STATE.with(|state| state.borrow_mut().as_mut().and_then(|state| state.result.take().map(|(v,b,e)| (v,b,e,std::mem::take(&mut state.steps))))
+            .ok_or_else(|| anyhow::anyhow!("missing canonical balance capture")))
+    }
+    #[cfg(test)]
+    mod tests {
+        use super::*;
+        #[test]
+        fn canonical_capture_cleanup_on_success_error_and_panic() {
+            assert!(take().is_err());
+            { let _capture = begin().unwrap(); assert!(begin().is_err()); assert!(take().is_err()); }
+            let failure = std::panic::catch_unwind(|| {
+                let _capture = begin().unwrap(); panic!("synthetic canonical capture failure");
+            });
+            assert!(failure.is_err());
+            { let _capture = begin().unwrap(); assert!(take().is_err()); }
+            assert!(begin().is_ok());
+        }
+    }
+}
